-- EkDum · optional scheduler (run AFTER ekdum_schema.sql and after the app is deployed).
-- Generated by "pnpm db:bundle". See docs/RUNBOOK.md, "Receipt retries".

-- ════════════════════════════════════════════════════════════════════════════
-- EkDum · 10 · Scheduler: retry the notification outbox every minute
-- ════════════════════════════════════════════════════════════════════════════
-- Uses pg_cron + pg_net to call the app's /api/jobs/notifications endpoint.
--
-- One-time setup after deploying the app (SQL editor), see docs/RUNBOOK.md:
--   select vault.create_secret('https://your-app-domain', 'ekdum_app_url');
--   select vault.create_secret('<the JOBS_SECRET value>',  'ekdum_jobs_secret');
-- Until both secrets exist this job does nothing, so it is safe to run early.

create extension if not exists pg_cron;
create extension if not exists pg_net;

create or replace function public.trigger_notification_processor()
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_url text;
  v_secret text;
begin
  -- Nothing to do → do not wake the app up.
  if not exists (
    select 1 from public.notification_jobs
    where (status = 'queued' and next_attempt_at <= now())
       or (status = 'sending' and locked_at < now() - interval '10 minutes')
  ) then
    return;
  end if;

  select decrypted_secret into v_url from vault.decrypted_secrets where name = 'ekdum_app_url';
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'ekdum_jobs_secret';
  if v_url is null or v_secret is null then
    return;
  end if;

  perform net.http_post(
    url := rtrim(v_url, '/') || '/api/jobs/notifications',
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_secret),
    body := '{}'::jsonb,
    timeout_milliseconds := 25000
  );
end;
$$;

revoke execute on function public.trigger_notification_processor() from public, anon, authenticated;

select cron.schedule('ekdum-notification-outbox', '* * * * *', $$select public.trigger_notification_processor()$$);
-- Keep the rate-limit table small.
select cron.schedule('ekdum-rate-limit-cleanup', '17 3 * * *',
  $$delete from public.rate_limits where window_start < now() - interval '1 day'$$);
